import math


class Shape:
    def area(self):
        return 0


class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def area(self):
        return math.pi * self.r ** 2


class Rectangle(Shape):
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h


class Square(Rectangle):
    def __init__(self, a):
        super().__init__(a, a)


def total_area(shapes):
    total = 0
    for kind, *args in shapes:
        if kind == "circle":
            shape = Circle(*args)
        elif kind == "rect":
            shape = Rectangle(*args)
        else:
            shape = Square(*args)
        total += shape.area()
    return round(total, 2)

